export const MAX_PROVIDER_TOOLS = 128;
const DEFAULT_PRESERVED_TOOL_NAMES = ["tool-search"];
export function limitProviderTools(tools, preserveNames = DEFAULT_PRESERVED_TOOL_NAMES) {
    if (tools.length <= MAX_PROVIDER_TOOLS)
        return tools;
    const preservedNames = new Set(preserveNames);
    const seen = new Set();
    const limited = [];
    for (const tool of tools) {
        if (!preservedNames.has(tool.name) || seen.has(tool.name))
            continue;
        limited.push(tool);
        seen.add(tool.name);
    }
    for (const tool of tools) {
        if (seen.has(tool.name))
            continue;
        limited.push(tool);
        if (limited.length === MAX_PROVIDER_TOOLS)
            return limited;
    }
    return limited.slice(0, MAX_PROVIDER_TOOLS);
}
